package com.hau.exam.domain.model;import java.time.Instant;import java.util.*;public record ExamVersion(UUID id,int versionNumber,List<ExamQuestionReference>questions,Instant createdAt){public ExamVersion{questions=List.copyOf(questions);long unique=questions.stream().map(ExamQuestionReference::questionId).distinct().count();if(unique!=questions.size())throw new IllegalArgumentException("Duplicate question in exam version");}}
